import math
def priority(task, state, tenant_boost=5.0, alpha=1.0, shrink=0.0,
             r_beta=0.0, map_scale=1.0, reduce_scale=1.0,
             join_scale=1.0, other_scale=1.0, weight_exp=0.0):
    tier = tenant_boost if task.tenant == 'premium' else 1.0

    if task.task_type == 'map':
        tf = map_scale
    elif task.task_type == 'reduce':
        tf = reduce_scale
    elif task.task_type == 'join':
        tf = join_scale
    else:
        tf = other_scale

    est = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    mean = max(state.mean_est, 1e-6)

    pred = est * tf * (r ** r_beta) + shrink * mean
    pred = max(pred, 1e-6)

    w = max(task.weight, 1e-6) ** weight_exp
    return tier * w / (pred ** alpha)  # tuned (tenant_boost=12.3,alpha=0.3,shrink=0,r_beta=0,map_scale=2.46,reduce_scale=0.459,join_scale=0.956,other_scale=0.69,weight_exp=0)

import math
def priority(task, state, premium=5.0, weight_power=1.0, resource_power=0.5, age=0.5, map_w=1.0, reduce_w=1.0, join_w=1.0, other_w=1.0):
    est = max(float(task.estimated_runtime), 1e-6)
    need = max(float(task.resource_need), 1e-6)
    w = max(float(task.weight), 1e-6) ** weight_power
    wait = max(0.0, state.now - task.release)
    tier = premium if task.tenant == 'premium' else 1.0
    tt = task.task_type
    if tt == 'map':
        tf = map_w
    elif tt == 'reduce':
        tf = reduce_w
    elif tt == 'join':
        tf = join_w
    else:
        tf = other_w
    return tier * w * tf * (1.0 + age * wait / est) / (est * (need ** resource_power))  # tuned (premium=12.3,weight_power=0.631,resource_power=1.16,age=0.356,map_w=2.17,reduce_w=0.311,join_w=0.435,other_w=1.43)

def priority(task, state, m=10.0, b=0.0, w=0.0, map_mult=1.0, reduce_mult=1.0, join_mult=1.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w
    type_mult = 1.0
    if task.task_type == 'map':
        type_mult = map_mult
    elif task.task_type == 'reduce':
        type_mult = reduce_mult
    elif task.task_type == 'join':
        type_mult = join_mult
    wait = max(0.0, state.now - task.release)
    age = 1.0 + b * wait / est
    return tier * type_mult * weight / est * age  # tuned (m=13.9,b=0,w=0,map_mult=0.893,reduce_mult=1.44,join_mult=0.489)

def priority(task, state, m=5.0, w_pow=1.0):
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w_pow
    return tier * weight / max(task.estimated_runtime, 1e-6)

def priority(task, state, m=10.0, mapf=1.0, redf=1.0, joinf=1.0, otherf=1.0, alpha=0.0, wpow=0.0):
    est = max(task.estimated_runtime, 1e-6)
