        tf = joinf
    else:
        tf = otherf
    return tier * tf * (weight ** wpow) / max(est * (need ** alpha), 1e-6)  # tuned (m=6.98,mapf=0.324,redf=0.526,joinf=0.382,otherf=1.04,alpha=0,wpow=0)
